CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('participant','organizer')),password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,statement TEXT NOT NULL,time_limit_ms INT NOT NULL,memory_limit_kb INT NOT NULL,owner_id BIGINT NOT NULL REFERENCES users);
CREATE TABLE IF NOT EXISTS task_tests(id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks ON DELETE CASCADE,input TEXT NOT NULL,output TEXT NOT NULL,is_hidden BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS contests(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',starts_at TIMESTAMPTZ NOT NULL,duration_minutes INT NOT NULL,organizer_id BIGINT NOT NULL REFERENCES users);
CREATE TABLE IF NOT EXISTS contest_tasks(contest_id BIGINT REFERENCES contests ON DELETE CASCADE,task_id BIGINT REFERENCES tasks,PRIMARY KEY(contest_id,task_id));
CREATE TABLE IF NOT EXISTS registrations(contest_id BIGINT REFERENCES contests ON DELETE CASCADE,user_id BIGINT REFERENCES users,PRIMARY KEY(contest_id,user_id));
CREATE TABLE IF NOT EXISTS matches(id BIGSERIAL PRIMARY KEY,mode TEXT NOT NULL CHECK(mode IN ('duel','team')),contest_id BIGINT NOT NULL REFERENCES contests,invite_code TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'waiting',creator_id BIGINT NOT NULL REFERENCES users,participant_ids BIGINT[] NOT NULL DEFAULT '{}',started_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,winner_id BIGINT REFERENCES users);
CREATE TABLE IF NOT EXISTS submissions(id BIGSERIAL PRIMARY KEY,contest_id BIGINT NOT NULL REFERENCES contests,task_id BIGINT NOT NULL REFERENCES tasks,user_id BIGINT NOT NULL REFERENCES users,match_id BIGINT REFERENCES matches,source_code TEXT NOT NULL,language TEXT NOT NULL,verdict TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),checked_at TIMESTAMPTZ,error TEXT);
CREATE TABLE IF NOT EXISTS integrity_reports(id BIGSERIAL PRIMARY KEY,contest_id BIGINT REFERENCES contests,created_at TIMESTAMPTZ DEFAULT now(),engine TEXT NOT NULL,details JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS integrity_conclusions(id BIGSERIAL PRIMARY KEY,contest_id BIGINT REFERENCES contests,organizer_id BIGINT REFERENCES users,subject_user_id BIGINT REFERENCES users,comment TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
